#!/usr/bin/env python3
"""Finite captured FLOW replay; no JVM, engine edits, or semantic query results invented.
Supports only the observed one-leaf FLOW no-MUST packets, with actual E retained. Cross-checks every
captured native completion fresh flag and fresh delta before counting membership.
"""
import collections,copy,hashlib,json,re
from pathlib import Path
base=Path(__file__).resolve().parent.parent
es=json.loads((base/'analysis/stirling-run8-full-trace-decoded.json').read_text())['events']
def norm(x):
 if isinstance(x,dict):return {k:norm(v)for k,v in x.items()if k not in ['id','notation']}
 if isinstance(x,list):return [norm(v)for v in x]
 return x
def js(x):return json.dumps(norm(x),sort_keys=True,separators=(',',':'))
def route(e):
 r=e['rawRecord'];return {k:r[k]for k in ['run','method','parent','child','exit','point','P']}
def strict(e,field):return js({**route(e),'packet':e['facts'][field]['rows']})
def native_owner(e,row):
 r=e['rawRecord'];m=re.search(r'block=BlockId\(ordinal=(-?\d+)\)',r['child']);assert m
 return js({**{k:r[k]for k in ['run','method','parent','point','P']},'childBlock':int(m.group(1)),'base':row['base'],'layer':row['layer']})
def covers(a,p,t,mx,e):
 if not a['mx']<=mx:return False
 for q in a['paths']:
  if q==p and(a['tail']=='ANY' or a['tail']==t and a['E']<=e):return True
  if a['tail']=='ANY' and len(q)<len(p) and p[:len(q)]==q and p[len(q)] not in a['E']:return True
 return False
def minus(r,others):return {**r,'paths':{p for p in r['paths']if not any(covers(s,p,r['tail'],r['mx'],r['E'])for s in others)}}
def clone(rows):return [{**r,'paths':set(r['paths'])}for r in rows]
def add_into(r,rows):
 r={**r,'paths':set(r['paths'])}
 while True:
  i=next((i for i,s in enumerate(rows)if s['tail']==r['tail']and s['mx']==r['mx']and s['E']==r['E']),None)
  if i is not None:
   rest=minus(r,rows)
   if not rest['paths']:return None
   rows[i]['paths']|=rest['paths'];return rest
  i=next((i for i,s in enumerate(rows)if s['tail']==r['tail']and s['paths']==r['paths']and(s['mx']==r['mx']or s['E']==r['E'])),None)
  if i is not None:
   old=rows[i];merged=old['mx']&r['mx'];me=old['E']&r['E']
   if merged==old['mx']and me==old['E']:return None
   rows.pop(i);r={**r,'mx':merged,'E':me};continue
  rest=minus(r,rows)
  if not rest['paths']:return None
  rows.append(rest);return rest

def canonical_any(rows):
 # Exact shared-coordinate cofinite join; then compatible MAY-prefix cover.
 # No positive marks are invented; mx intersection is exact allowed-set union.
 at={}
 others=[]
 for r in rows:
  if r['tail']!='ANY':others.append(r);continue
  for p in r['paths']:at[p]=at[p]&r['mx']if p in at else r['mx']
 kept={p:mx for p,mx in at.items()if not any(len(q)<len(p)and p[:len(q)]==q and qm<=mx for q,qm in at.items())}
 by=collections.defaultdict(set)
 for p,mx in kept.items():by[mx].add(p)
 return others+[{'tail':'ANY','E':frozenset(),'mx':mx,'paths':ps}for mx,ps in by.items()]

def group_add(before,r):
 if r['tail']!='ANY':
  after=clone(before);delta=add_into(r,after);return after,([]if delta is None else[delta])
 if not before:
  return canonical_any([r]),[r]
 staged=clone(before)
 if add_into(r,staged)is None:return before,[]
 after=canonical_any(staged);delta=[minus(x,before)for x in after];return after,[x for x in delta if x['paths']]
def scalar(e,f):
 rows=e['facts'][f]['rows'];assert len(rows)==1 and e['facts'][f]['scalarExpansionComplete']
 row=rows[0];assert row['mark']=='FLOW'and row['protected']is False and row['tail']in['ANY','STAR','EXACT']
 return row,{'tail':row['tail'],'E':frozenset(row['E']),'mx':frozenset(row['mx']),'paths':{tuple(row['path'])}}
def exact_member(state,r):return any(s['tail']==r['tail']and s['mx']==r['mx']and s['E']==r['E']and r['paths']<=s['paths']for s in state)
def serial(r):return {'tail':r['tail'],'E':sorted(r['E']),'mx':sorted(r['mx']),'paths':[list(p)for p in sorted(r['paths'])]}
state={};prior={};offered={};items=[];mismatches=[];applied=None
for e in es:
 raw=e['rawRecord'];stage=raw['stage']
 if stage=='local-applied':
  applied=e;row,packet=scalar(e,'value');owner=native_owner(e,row);current=state.get(owner,[])
  snap={'rawMemberNow':exact_member(current,packet),'historicalFresh':prior.get(strict(e,'value')),'stateBefore':[serial(x)for x in current]}
 if stage!='local-completion':continue
 row,packet=scalar(e,'offered');owner=native_owner(e,row);before=state.get(owner,[]);after,delta=group_add(before,packet)
 expected=raw['fresh'];actual=bool(delta)
 if expected!=actual:mismatches.append({'completion':raw['sequence'],'expectedFresh':expected,'derivedFresh':actual,'before':[serial(x)for x in before],'after':[serial(x)for x in after]})
 if expected and actual:
  _,native_delta=scalar(e,'delta')
  if len(delta)!=1 or delta[0]!=native_delta:mismatches.append({'completion':raw['sequence'],'deltaMismatch':True,'nativeDelta':serial(native_delta),'derivedDelta':[serial(x)for x in delta]})
 state[owner]=after
 ck=strict(e,'offered');same_raw=strict(applied,'value')==ck
 item={'applied':applied['rawRecord']['sequence'],'completion':raw['sequence'],'postDuplicate':ck in offered,'rawEqualsKept':same_raw,'rawEqualsPriorFresh':snap['historicalFresh']is not None,'priorFresh':snap['historicalFresh'],'rawExactCurrentCoordinate':snap['rawMemberNow'],'offered':row,'stateBeforeApplied':snap['stateBefore'],'fullRouteAndP':route(applied)}
 items.append(item)
 offered.setdefault(ck,raw['sequence'])
 if expected:prior.setdefault(strict(e,'delta'),raw['sequence'])
assert len(items)==792
rep=[x for x in items if x['postDuplicate']]
assert len(rep)==542
print('MODEL_CROSSCHECK',len(items),'mismatches',len(mismatches))
print('POST542 rawhistoricalfresh',sum(x['rawEqualsPriorFresh']for x in rep),'rawcurrentcoordinate',sum(x['rawExactCurrentCoordinate']for x in rep),'both',sum(x['rawEqualsPriorFresh']and x['rawExactCurrentCoordinate']for x in rep))
print('breakdown',collections.Counter((x['rawEqualsPriorFresh'],x['rawExactCurrentCoordinate'],x['rawEqualsKept'])for x in rep))
print('all792 currentexact',sum(x['rawExactCurrentCoordinate']for x in items))
print('mismatch',mismatches[:3])
out={'schema':'opentaint.stirling.pre-gate-current-exact-membership.v1','status':'FINITE_SOURCE_REPLAY_NATIVE_FLAGS_DELTA_CROSSCHECK','inputSha256':hashlib.sha256((base/'analysis/stirling-run8-full-trace-decoded.json').read_bytes()).hexdigest(),'scriptSha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'controls':{'completionEvents':len(items),'freshFlagAndDeltaMismatches':len(mismatches),'mismatches':mismatches},'counts':{'postRestrictionExactRepeatedEvents':len(rep),'rawEqualsEarlierFreshAtStrictRoute':sum(x['rawEqualsPriorFresh']for x in rep),'rawExactCurrentCoordinateNativeStore':sum(x['rawExactCurrentCoordinate']for x in rep),'rawExactCurrentAndEarlierFreshStrictRoute':sum(x['rawExactCurrentCoordinate']and x['rawEqualsPriorFresh']for x in rep),'allRawExactCurrentCoordinate':sum(x['rawExactCurrentCoordinate']for x in items)},'items':items,'limits':['This is a finite FLOW-only source replay, not direct historical heap/store inspection and not a generic AP implementation proof.','Each packet has one FLOW leaf; MAY E is empty; STAR has Eempty or {204}; tails are MAY/STAR/EXACT; no MUST or concrete protection case is counted.','Native storage owner is parent owner + ChildPoint(child block,completion point)+P+base/layer. It does not distinguish child ingress/physical exit; strict-route historical witnesses do.','Exact current-coordinate membership is stronger than semantic prefix coverage. A prior fresh leaf can be absent now after canonicalization.','No query observer, current DATA, subscription, C5, source or Target effect is executed by this reader. No policy change selected.']}
p=base/'analysis/stirling-pre-gate-current-membership.json';p.write_text(json.dumps(out,indent=2)+'\n')
print(p,p.stat().st_size)
